import { BlockIframeData } from './BlockIframeData';
import { AddedBlockBridgeEvent, DuplicatedBlockBridgeEvent, EnterComponentBridgeEvent, EnterEditModeBridgeEvent, HighlightComponentBridgeEvent, HoverComponentBridgeEvent, MovedBlockBridgeEvent } from './BridgeEvent';
import { ActionsMenuItem, BlokActionName, BridgeCallback, BridgeConfig, BridgeEventMap, BridgeEventName, BridgePrivateParams, ComponentNames, DecoratedElement, EditActionBlokRef, EditedBlokPayload, ElementOffset, NavigationBreadcrumb, OutboundMessage } from './internal/types';
/**
 * Communicate a website with the Storyblok Editor
 *
 * @class StoryblokBridgePrivate
 */
export default class StoryblokBridgePrivate {
    appVersion: EnterEditModeBridgeEvent['appVersion'];
    inEditor: boolean;
    initialized: boolean;
    currentUid: string | null;
    storyId: string;
    componentNames: ComponentNames;
    outlineOnMoveInterval: ReturnType<typeof setTimeout> | null;
    calcInterval: number | null;
    canAddBlocks: boolean;
    canMoveForward: boolean;
    canMoveBackward: boolean;
    canDeleteBlocks: boolean;
    navigationBreadcrumbs: NavigationBreadcrumb[];
    focusState: boolean;
    actionsEnabled: boolean;
    hinter: HTMLDivElement;
    highlighter: HTMLDivElement;
    overlay: HTMLDivElement;
    componentBase: HTMLDivElement;
    componentLabel: HTMLSpanElement;
    breadcrumbsButtonMenu: HTMLButtonElement;
    breadcrumbsMenu: HTMLDivElement;
    actionsMenu: HTMLDivElement;
    actionsMenuButton: HTMLButtonElement;
    actionsMenuItems: ActionsMenuItem[] | null;
    events: BridgeEventMap;
    _decoratedElements: DecoratedElement[];
    _onMessage: ((event: MessageEvent) => void) | null;
    _onMouseMove: (() => void) | null;
    _onWindowClick: ((event: MouseEvent) => void) | null;
    config: BridgeConfig;
    constructor(props?: BridgePrivateParams);
    get isInIframe(): boolean;
    /**
     * Return the correct protocol to sync with the Editor
     */
    get csProtocol(): string;
    /**
     * Return the URL from parent to allow the communication
     */
    get targetOrigin(): string;
    /**
     * Return the last element in navigation breadcrumb
     * which is the current selected element
     */
    get lastBreadcrumbItem(): Partial<NavigationBreadcrumb>;
    isInEditor(): boolean;
    /**
     * Transform comments in the DOM to data-blok-c and data-blok-uid
     */
    init(): void;
    sendDataToEditor(payload: OutboundMessage): void;
    /**
     * Initialize the styles in the page, creating the hinter and highlighter DOM nodes
     * and inject the styles in a style tag in the page
     */
    buildBridgeStyles(): void;
    createBridgeStylesheet(): void;
    /**
     * hinter is used to highlight when you hover on editor then the blok on inside frame highlights
     */
    createHinter(): void;
    createHighlighter(): void;
    createOverlay(): void;
    calculateElementPosition(el: HTMLElement, uid: string): boolean;
    getElementOffset(el: Element): ElementOffset;
    resetAllEvents(): void;
    addMessageListener(): void;
    receiveMessageFromApp(event: MessageEvent): void;
    emit(action: string, ...payload: unknown[]): void;
    outlineOnMoveHandler(): void;
    outlineOnMove(): void;
    /**
     * Subscribe a callback to one event or to a set of them
     */
    on<Name extends BridgeEventName>(event: Name | Name[], callback: BridgeCallback<Name>): void;
    subscribeEvent<Name extends BridgeEventName>(eventName: Name, callbackEvent: BridgeCallback<Name>): void;
    /**
     * ping the Editor and cb callback function is that receives the class instance
     */
    pingEditor(cb: (instance: StoryblokBridgePrivate) => void): void;
    handlePingBack(cb: (instance: StoryblokBridgePrivate) => void): () => void;
    handleEditedBlok(event: EditedBlokPayload): void;
    handleAddMoveBlok(event: AddedBlockBridgeEvent | MovedBlockBridgeEvent): void;
    handleDeselectBlock(): void;
    handleDuplicatedBlok(event: DuplicatedBlockBridgeEvent): void;
    handleWindowClick(event: MouseEvent): void;
    /**
     * Set focus on the element or send the clicked block information to the application
     */
    handleOpenBlok(target: Element | null, event?: MouseEvent): void;
    enterEditmode(attr: Partial<EnterEditModeBridgeEvent>): void;
    /**
     * Highlights component when selecting in the sidebar via checkbox
     */
    highlightComponent(data: HighlightComponentBridgeEvent): void;
    /**
     * Show hinter when hovering block in the sidebar
     */
    hoverComponent(data: HoverComponentBridgeEvent): void;
    toggleFocusElement(target: Element | null, removeFocus?: boolean): void;
    showFocusedElement(el: HTMLElement): void;
    handleBlokActions(action: BlokActionName): void;
    hideElement(el: HTMLElement): void;
    showElement(el: HTMLElement): void;
    toggleElement(el: HTMLElement): void;
    /**
     * triggered when navigation to block from sidebar
     */
    enterComponent(event: EnterComponentBridgeEvent): void;
    scrollIntoView(target: Element | null): void;
    openBlok(blok: EditActionBlokRef): void;
    createComponentContext(): void;
    createComponentBase(): void;
    createComponentLabel(): void;
    createComponentButtonLabel(): void;
    updateComponentLabel(blok: BlockIframeData): void;
    updateComponentBase(blok: BlockIframeData): void;
    createBreadcrumbsMenuButton(): void;
    createBreadcrumbsMenu(): void;
    updateBreadcrumbsMenu(breadcrumbs: NavigationBreadcrumb[]): void;
    createActionsMenuButton(): void;
    createActionsMenuItems(): void;
    createActionsMenu(): void;
    updateActionsMenu(): void;
    /**
     * Tear down all listeners, timers, DOM nodes and styles created by the bridge.
     */
    destroy(): void;
}
